class CavaProductKind(str, Enum):
    PERSONAL = "PERSONAL"
    CORPORATIVA = "CORPORATIVA"


class BenefitLine(str, Enum):
    ALIMENTOS = "ALIMENTOS"
    BEBIDAS = "BEBIDAS"
    AMBOS = "AMBOS"


@dataclass(frozen=True)
class BenefitTimeWindow:
    start_time: str
    end_time: str
    hard_cutoff_time: Optional[str] = None


@dataclass(frozen=True)
class MembershipBenefitPolicy:
    policy_id: str
    product_kind: CavaProductKind
    benefit_line: BenefitLine
    valid_from: str
    valid_to: Optional[str]
    allowed_weekdays: tuple[int, ...]
    time_windows: tuple[BenefitTimeWindow, ...]
    registered_users_required: bool
    business_purpose_required: bool
    max_people: Optional[int] = None
    restriction_codes: tuple[str, ...] = ()


def validate_benefit_time_window(window: BenefitTimeWindow) -> None:
    if not str(window.start_time or "").strip() or not str(window.end_time or "").strip():
        raise ValueError("La ventana de beneficio requiere start_time y end_time")
    if window.end_time <= window.start_time:
        raise ValueError("end_time debe ser posterior a start_time")
    if window.hard_cutoff_time is not None and window.hard_cutoff_time < window.end_time:
        raise ValueError("hard_cutoff_time no puede ser anterior a end_time")


def validate_membership_benefit_policy(policy: MembershipBenefitPolicy) -> None:
    if not str(policy.policy_id or "").strip():
        raise ValueError("MembershipBenefitPolicy requiere policy_id")
    if policy.valid_to is not None and policy.valid_to < policy.valid_from:
        raise ValueError("valid_to no puede ser anterior a valid_from")
    if not policy.allowed_weekdays:
        raise ValueError("Debe existir al menos un dia permitido")
    if any(day < 1 or day > 7 for day in policy.allowed_weekdays):
        raise ValueError("allowed_weekdays usa ISO weekday 1..7")
    if not policy.time_windows:
        raise ValueError("Debe existir al menos una ventana horaria")
    for window in policy.time_windows:
        validate_benefit_time_window(window)
    if policy.max_people is not None and policy.max_people <= 0:
        raise ValueError("max_people debe ser positivo cuando se configure")
    if policy.product_kind == CavaProductKind.CORPORATIVA:
        if not policy.registered_users_required:
            raise ValueError("La Cava CORPORATIVA requiere usuarios registrados")
        if not policy.business_purpose_required:
            raise ValueError("La Cava CORPORATIVA requiere elegibilidad de negocio")


def benefit_applies_to_line(policy: MembershipBenefitPolicy, requested_line: BenefitLine) -> bool:
    validate_membership_benefit_policy(policy)
    if policy.benefit_line == BenefitLine.AMBOS:
        return requested_line in {BenefitLine.ALIMENTOS, BenefitLine.BEBIDAS, BenefitLine.AMBOS}
    if requested_line == BenefitLine.AMBOS:
        return False
    return policy.benefit_line == requested_line
